import sys

def count_undoubtedly_lucky(n):
    s = str(n)
    length = len(s)
    total = 0

    # Precompute powers of 10
    pow10 = [1] * (length + 1)
    for i in range(1, length + 1):
        pow10[i] = pow10[i - 1] * 10

    # Count numbers with fewer digits than n
    for d in range(1, length):
        total += 9 * pow10[d - 1]  # all numbers with d digits

    # Count numbers with same length as n
    for i, ch in enumerate(s):
        digit = int(ch)
        pos = i + 1
        remaining = length - pos

        # Case 1: all digits in prefix are equal
        if pos == 1:
            # Leading digit can be 1..digit-1
            if digit > 1:
                total += digit - 1
        else:
            # For each possible digit x in prefix positions
            for x in range(10):
                if x > digit:
                    break
                if x == 0 and pos == 1:
                    continue  # no leading zero
                if x < digit:
                    # All remaining digits can be anything
                    total += pow10[remaining]
                else:  # x == digit
                    # Remaining digits must be >= x to keep number <= n
                    # But since we only count numbers with all digits equal to x,
                    # there's exactly one such number if x-digit prefix matches n's prefix
                    if i == length - 1:
                        total += 1

        # Case 2: prefix uses two distinct digits
        # We consider all pairs (x, y) with x != y
        for x in range(10):
            if x == 0 and pos == 1:
                continue  # no leading zero
            for y in range(10):
                if x == y:
                    continue

                # Count numbers where current position uses y and previous positions use x or y
                # but the number is <= n
                # This is complex; instead, we use a simpler overall approach below.
                pass

        # The above attempt is too complex; break and use a different method
        break

    # Simpler method: brute force over all numbers up to n (n <= 1e9)
    # but optimized by checking digits quickly.
    # This is acceptable since 1e9 operations is too many, but we won't actually do that.
    # Instead, we directly compute using digit DP.

    # Digit DP: dp[pos][tight][mask]
    # mask: bitmask of digits used (0..9)
    from functools import lru_cache

    digits = list(map(int, s))

    @lru_cache(None)
    def dp(pos, tight, started, mask):
        if pos == len(digits):
            if not started:
                return 0
            # Count if mask has 1 or 2 bits set
            if mask == 0:
                return 0
            if mask & (mask - 1) == 0:
                return 1
            # Check if exactly two bits
            if (mask & (mask - 1)) != 0 and (mask & (mask - 1) & ((mask & (mask - 1)) - 1)) == 0:
                return 1
            return 0

        limit = digits[pos] if tight else 9
        res = 0
        for d in range(0, limit + 1):
            ntight = tight and (d == limit)
            nstarted = started or (d != 0)
            nmask = mask
            if nstarted:
                nmask |= 1 << d
            res += dp(pos + 1, ntight, nstarted, nmask)
        return res

    return dp(0, True, False, 0)


def main():
    n = int(sys.stdin.readline().strip())
    print(count_undoubtedly_lucky(n))

